import { startLogin } from "@/const";
import { useAuth } from "@/_core/hooks/useAuth";
import { trpc } from "@/lib/trpc";
import type { College, Cutoff } from "@shared/collegeData";
import {
  ArrowRight,
  BarChart3,
  BookOpen,
  Bookmark,
  Check,
  ChevronDown,
  ChevronRight,
  CircleHelp,
  ExternalLink,
  Gauge,
  GraduationCap,
  Heart,
  Landmark,
  LayoutDashboard,
  ListFilter,
  LockKeyhole,
  LogOut,
  MapPin,
  Menu,
  Minus,
  Plus,
  Search,
  ShieldCheck,
  SlidersHorizontal,
  Sparkles,
  Star,
  Target,
  Trophy,
  X,
  Zap,
} from "lucide-react";
import { useEffect, useMemo, useState, type ReactNode } from "react";
import { Link, useLocation, useParams } from "wouter";

const NAV = [
  ["/", "Home"],
  ["/colleges", "Explore colleges"],
  ["/compare", "Compare"],
  ["/guidance", "Guidance"],
  ["/about", "About"],
] as const;

function cx(...classes: Array<string | false | null | undefined>) {
  return classes.filter(Boolean).join(" ");
}

function Logo() {
  return (
    <Link href="/" className="group flex items-center gap-2.5" aria-label="EduCompass home">
      <span className="grid size-9 place-items-center rounded-xl bg-[#1f2a5a] text-[#f7f7ff] shadow-[0_5px_18px_rgba(23,59,52,0.22)] transition-transform duration-200 group-hover:-rotate-3">
        <CompassMark />
      </span>
      <span className="leading-none">
        <span className="block font-display text-[1.12rem] font-bold tracking-[-0.04em] text-[#1f2a5a]">EduCompass</span>
        <span className="mt-1 block text-[9px] font-semibold uppercase tracking-[0.18em] text-[#8991ad]">One platform. Every answer.</span>
      </span>
    </Link>
  );
}

function CompassMark() {
  return <span className="relative block size-4 rounded-full border-2 border-[#d8d9ff]"><span className="absolute left-1/2 top-[2px] h-2 w-[2px] -translate-x-1/2 rotate-[34deg] rounded-full bg-[#d8d9ff]" /><span className="absolute bottom-[2px] left-1/2 h-1.5 w-[2px] -translate-x-1/2 rotate-[34deg] rounded-full bg-[#9b94ee]" /></span>;
}

function Shell({ children, active = "" }: { children: ReactNode; active?: string }) {
  const [menuOpen, setMenuOpen] = useState(false);
  const { user, isAuthenticated, logout } = useAuthSafe();
  return (
    <div className="min-h-screen bg-[#f8f9ff] text-[#18352f]">
      <div className="pointer-events-none fixed inset-x-0 top-0 z-0 h-80 bg-[radial-gradient(circle_at_20%_10%,rgba(214,236,156,0.28),transparent_32%),radial-gradient(circle_at_90%_0%,rgba(159,218,197,0.22),transparent_28%)]" />
      <header className="relative z-20 border-b border-[#e4e7f2]/90 bg-[#f8f9ff]/90 backdrop-blur-xl">
        <div className="container flex h-[76px] items-center justify-between gap-4">
          <Logo />
          <nav className="hidden items-center gap-7 lg:flex">
            {NAV.map(([href, label]) => <Link key={href} href={href} className={cx("nav-link", (active === href || (active === "/colleges" && href === "/") && false) && "nav-link-active")}>{label}</Link>)}
          </nav>
          <div className="hidden items-center gap-2 sm:flex">
            {isAuthenticated ? (
              <Link href="/student" className="flex items-center gap-2 rounded-full border border-[#dce0ef] bg-white px-3.5 py-2 text-sm font-semibold text-[#234b41] shadow-sm transition hover:-translate-y-0.5"><span className="grid size-6 place-items-center rounded-full bg-[#e5e4ff] text-[10px]">{user?.name?.[0] ?? "S"}</span>{user?.name?.split(" ")[0] ?? "Workspace"}</Link>
            ) : <button onClick={startLogin} className="button-ghost"><LockKeyhole className="size-3.5" /> Student Login</button>}
            <Link href="/admin" className="button-ghost"><ShieldCheck className="size-3.5" /> Admin Login</Link>
            <Link href="/colleges" className="button-primary">Find your college <ArrowRight className="size-4" /></Link>
          </div>
          <button className="grid size-10 place-items-center rounded-xl border border-[#dce0ef] bg-white lg:hidden" onClick={() => setMenuOpen((open) => !open)} aria-label="Toggle menu"><Menu className="size-5" /></button>
        </div>
        {menuOpen && <div className="container pb-4 lg:hidden"><div className="grid gap-1 rounded-2xl border border-[#dfe8dc] bg-white p-2 shadow-lg">{NAV.map(([href, label]) => <Link key={href} href={href} onClick={() => setMenuOpen(false)} className="rounded-xl px-3 py-2.5 text-sm font-semibold hover:bg-[#eff6e7]">{label}</Link>)}<Link href="/student" onClick={() => setMenuOpen(false)} className="rounded-xl px-3 py-2.5 text-sm font-semibold hover:bg-[#eff6e7]"><LockKeyhole className="mr-2 inline size-4" />Student Login</Link><Link href="/admin" onClick={() => setMenuOpen(false)} className="rounded-xl px-3 py-2.5 text-sm font-semibold hover:bg-[#eff6e7]"><ShieldCheck className="mr-2 inline size-4" />Admin Login</Link>{isAuthenticated && <button onClick={() => void logout()} className="flex items-center gap-2 rounded-xl px-3 py-2.5 text-left text-sm font-semibold text-red-600 hover:bg-red-50"><LogOut className="size-4" /> Log out</button>}</div></div>}
      </header>
      <main className="relative z-10">{children}</main>
      <footer className="relative z-10 mt-20 border-t border-[#e4e7f2] bg-[#eef0ff]">
        <div className="container grid gap-10 py-12 md:grid-cols-[1.2fr_0.8fr_0.8fr]">
          <div><Logo /><p className="mt-5 max-w-sm text-sm leading-6 text-[#727b9c]">A clearer way to discover engineering colleges, understand branch cutoffs, and build a shortlist you can stand behind.</p></div>
          <div><p className="eyebrow">Explore</p><div className="mt-4 grid gap-2.5 text-sm text-[#727b9c]"><Link href="/colleges" className="hover:text-[#1f2a5a]">College finder</Link><Link href="/compare" className="hover:text-[#1f2a5a]">Compare colleges</Link><Link href="/guidance" className="hover:text-[#1f2a5a]">Admission guidance</Link></div></div>
          <div><p className="eyebrow">Data promise</p><p className="mt-4 text-sm leading-6 text-[#727b9c]">Cutoffs are shown with their exam, category, CAP round, year, and official source link so context never gets lost.</p></div>
        </div>
        <div className="container flex flex-col justify-between gap-2 border-t border-[#dce8d5] py-5 text-xs text-[#8991ad] sm:flex-row"><span>© 2026 EduCompass</span><span>Built for better admission decisions.</span></div>
      </footer>
    </div>
  );
}

function useAuthSafe() {
  return useAuth();
}

function Eyebrow({ children }: { children: ReactNode }) { return <p className="eyebrow">{children}</p>; }
function SectionHeading({ kicker, title, body, action }: { kicker?: string; title: string; body?: string; action?: ReactNode }) { return <div className="flex flex-col justify-between gap-5 md:flex-row md:items-end"><div>{kicker && <Eyebrow>{kicker}</Eyebrow>}<h2 className="mt-2 max-w-2xl font-display text-3xl font-bold leading-[1.05] tracking-[-0.045em] text-[#1f2a5a] sm:text-4xl">{title}</h2>{body && <p className="mt-4 max-w-xl text-[15px] leading-7 text-[#727b9c]">{body}</p>}</div>{action}</div>; }

function Hero() {
  const [percentile, setPercentile] = useState("98.50");
  return <section className="container grid gap-10 pb-16 pt-14 lg:grid-cols-[1.03fr_0.97fr] lg:items-center lg:pb-24 lg:pt-20">
    <div className="max-w-2xl"><div className="pill mb-6"><span className="size-1.5 rounded-full bg-[#ef9c59]" />2025–26 official CAP data, made legible</div><h1 className="font-display text-[3.5rem] font-extrabold leading-[0.94] tracking-[-0.075em] text-[#1f2a5a] sm:text-[5.1rem]">Choose your next<br /><span className="text-[#635bdb]">engineering chapter.</span></h1><p className="mt-7 max-w-xl text-lg leading-8 text-[#607a72]">Search colleges, read branch-wise cutoffs, and compare the details that matter — all in one calm, decision-ready space.</p><div className="mt-8 flex flex-col gap-3 sm:flex-row"><Link href="/colleges" className="button-primary h-12 px-6">Explore colleges <ArrowRight className="size-4" /></Link><Link href="/guidance" className="button-ghost h-12 px-6">How it works <ChevronRight className="size-4" /></Link></div><div className="mt-9 flex flex-wrap items-center gap-5 text-xs font-semibold text-[#727b9c]"><span className="flex items-center gap-2"><ShieldCheck className="size-4 text-[#78a35d]" /> Official source context</span><span className="flex items-center gap-2"><Zap className="size-4 text-[#635bdb]" /> Fast shortlisting</span></div></div>
    <div className="relative"><div className="absolute -left-8 -top-10 size-28 rounded-full bg-[#d8d9ff]/60 blur-2xl" /><div className="relative overflow-hidden rounded-[2rem] border border-[#d8dcef] bg-[#e8f2dc] p-5 shadow-[0_22px_50px_rgba(44,81,61,0.12)] sm:p-7"><div className="flex items-center justify-between"><div><p className="eyebrow text-[#6a8b70]">Your admission snapshot</p><p className="mt-2 text-sm font-semibold text-[#36584f]">A smarter starting point</p></div><span className="grid size-10 place-items-center rounded-2xl bg-[#1f2a5a] text-[#d8d9ff]"><Target className="size-5" /></span></div><div className="mt-6 rounded-2xl bg-white/85 p-5"><div className="flex items-end justify-between"><div><p className="text-xs font-bold uppercase tracking-[0.12em] text-[#759087]">MHT-CET percentile</p><p className="mt-1 font-display text-4xl font-bold tracking-[-0.05em] text-[#1f2a5a]">{percentile}</p></div><span className="rounded-full bg-[#e5e4ff] px-2.5 py-1 text-[11px] font-bold text-[#68862f]">Target set</span></div><input type="range" min="60" max="100" step="0.01" value={percentile} onChange={(e) => setPercentile(e.target.value)} className="mt-5 w-full accent-[#635bdb]" /><div className="mt-2 flex justify-between text-[10px] font-bold uppercase tracking-[0.12em] text-[#9299b2]"><span>60 percentile</span><span>100 percentile</span></div></div><div className="mt-4 grid grid-cols-2 gap-3"><MiniStat label="Shortlist" value="06 colleges" icon={<Bookmark className="size-4" />} /><MiniStat label="Best match" value="PICT · CSE" icon={<Sparkles className="size-4" />} /></div><div className="mt-4 flex items-center gap-3 rounded-2xl bg-[#1f2a5a] p-4 text-[#f7f7ff]"><div className="grid size-9 place-items-center rounded-xl bg-[#315d51]"><BarChart3 className="size-4 text-[#d8d9ff]" /></div><div><p className="text-xs font-bold uppercase tracking-[0.1em] text-[#c1c8e5]">Useful by design</p><p className="mt-1 text-sm font-semibold">Compare cutoffs with their context.</p></div></div></div><div className="absolute -bottom-5 -left-5 hidden rounded-2xl border border-[#dfebd2] bg-white px-4 py-3 shadow-xl sm:block"><div className="flex items-center gap-2"><span className="grid size-7 place-items-center rounded-lg bg-[#fff0df] text-[#635bdb]"><Star className="size-3.5 fill-current" /></span><span className="text-xs font-bold text-[#38584e]">Decision clarity, not data noise</span></div></div></div>
  </section>;
}

function MiniStat({ label, value, icon }: { label: string; value: string; icon: ReactNode }) { return <div className="rounded-2xl border border-[#dce0ef] bg-white/65 p-4"><div className="flex items-center gap-2 text-[#789a66]">{icon}<span className="text-[10px] font-bold uppercase tracking-[0.12em]">{label}</span></div><p className="mt-2 text-sm font-bold text-[#31564b]">{value}</p></div>; }

function Home() {
  const stats = trpc.catalog.stats.useQuery();
  const sources = trpc.admin.sources.useQuery();
  return <Shell active="/"><Hero /><section className="container pb-20"><div className="grid gap-3 sm:grid-cols-3"><Metric value={stats.data?.colleges ?? 6} label="curated colleges" /><Metric value={stats.data?.branches ?? 24} label="branch cutoffs" /><Metric value="1" label="official source trail" /></div></section><section className="border-y border-[#e4e7f2] bg-white/60"><div className="container py-16"><SectionHeading kicker="The compass method" title="Everything you need to move from anxious research to a confident shortlist." body="EduCompass brings together the questions students usually answer across too many tabs — and gives each number the context it deserves." /><div className="mt-10 grid gap-4 md:grid-cols-3"><FeatureCard icon={<ListFilter />} number="01" title="Filter with intent" body="Start with city, branch, fee range, or the percentile you actually have." /><FeatureCard icon={<BarChart3 />} number="02" title="See the full picture" body="Read cutoffs alongside fees, intake, placements, and official links." /><FeatureCard icon={<ScaleIcon />} number="03" title="Compare, then decide" body="Shortlist up to three colleges and scan the differences side by side." /></div></div></section><section className="container py-20"><SectionHeading kicker="Built around your questions" title="A calmer college search, one useful answer at a time." action={<Link href="/colleges" className="button-secondary">Start exploring <ArrowRight className="size-4" /></Link>} /><div className="mt-10 grid gap-5 lg:grid-cols-[1.3fr_0.7fr]"><div className="rounded-[1.75rem] bg-[#1f2a5a] p-7 text-[#f7f7ff] sm:p-9"><div className="flex items-start justify-between gap-6"><div><p className="eyebrow text-[#c1c8e5]">Source-aware by default</p><h3 className="mt-3 max-w-lg font-display text-3xl font-bold tracking-[-0.045em]">Not just a cutoff number. The round, category, year, and source too.</h3></div><div className="grid size-12 shrink-0 place-items-center rounded-2xl bg-[#3b4784] text-[#d8d9ff]"><ShieldCheck className="size-6" /></div></div><div className="mt-9 flex flex-wrap gap-2">{["CAP Round I", "GOPENS", "MHT-CET", "2025–26"].map((tag) => <span key={tag} className="rounded-full border border-[#5964a0] bg-[#303b70] px-3 py-1.5 text-xs font-semibold text-[#dfe2f5]">{tag}</span>)}</div><a href={sources.data?.officialCutoffPdf ?? "https://fe2026.mahacet.org/2025/2025ENGG_CAP1_CutOff.pdf"} target="_blank" rel="noreferrer" className="mt-8 inline-flex items-center gap-2 text-sm font-bold text-[#d8d9ff] hover:text-white">Open official cutoff publication <ExternalLink className="size-3.5" /></a></div><div className="rounded-[1.75rem] border border-[#dce7d7] bg-[#eef0ff] p-7"><span className="grid size-11 place-items-center rounded-2xl bg-white text-[#635bdb] shadow-sm"><GraduationCap className="size-5" /></span><h3 className="mt-6 font-display text-2xl font-bold tracking-[-0.04em] text-[#1f2a5a]">Student workspace</h3><p className="mt-3 text-sm leading-6 text-[#727b9c]">Sign in to keep your shortlist, return to your comparisons, and pick up where you left off.</p><Link href="/student" className="mt-7 inline-flex items-center gap-2 text-sm font-bold text-[#635bdb]">Open workspace <ArrowRight className="size-4" /></Link></div></div></section></Shell>;
}

function Metric({ value, label }: { value: string | number; label: string }) { return <div className="rounded-2xl border border-[#e0e3f0] bg-white/80 px-5 py-4"><p className="font-display text-2xl font-bold tracking-[-0.04em] text-[#1f2a5a]">{value}</p><p className="mt-1 text-xs font-bold uppercase tracking-[0.12em] text-[#9299b2]">{label}</p></div>; }
function FeatureCard({ icon, number, title, body }: { icon: ReactNode; number: string; title: string; body: string }) { return <div className="group rounded-[1.5rem] border border-[#e0e3f0] bg-[#f5f6ff] p-6 transition duration-200 hover:-translate-y-1 hover:border-[#cfd3ea] hover:bg-white hover:shadow-[0_16px_35px_rgba(44,81,61,0.08)]"><div className="flex items-center justify-between"><span className="grid size-10 place-items-center rounded-xl bg-white text-[#635bdb] shadow-sm">{icon}</span><span className="font-display text-3xl font-bold tracking-[-0.06em] text-[#d9e7d2] group-hover:text-[#bbd29e]">{number}</span></div><h3 className="mt-8 font-display text-xl font-bold tracking-[-0.035em] text-[#1f2a5a]">{title}</h3><p className="mt-3 text-sm leading-6 text-[#727b9c]">{body}</p></div>; }
function ScaleIcon() { return <span className="text-lg font-bold">⇄</span>; }

function FinderHeader({ title = "Explore engineering colleges", body = "Search a curated set of Maharashtra colleges with branch-wise CAP cutoffs and source context." }: { title?: string; body?: string }) { return <section className="container pb-8 pt-12 sm:pt-16"><Eyebrow>College finder</Eyebrow><div className="mt-2 flex flex-col justify-between gap-5 lg:flex-row lg:items-end"><div><h1 className="font-display text-4xl font-bold tracking-[-0.055em] text-[#1f2a5a] sm:text-5xl">{title}</h1><p className="mt-4 max-w-2xl text-[15px] leading-7 text-[#727b9c]">{body}</p></div><div className="flex items-center gap-2 rounded-2xl border border-[#dce0ef] bg-white px-4 py-3 text-sm text-[#6c837c]"><ShieldCheck className="size-4 text-[#78a35d]" /> Official source trail included</div></div></section>; }

function Finder() {
  const [query, setQuery] = useState("");
  const [city, setCity] = useState("all");
  const [branch, setBranch] = useState("all");
  const [maxFee, setMaxFee] = useState(300000);
  const [minPercentile, setMinPercentile] = useState(0);
  const [shortlist, setShortlist] = useShortlist();
  const filters = trpc.catalog.filters.useQuery();
  const input = useMemo(() => ({ query, city, branch, maxFee, minPercentile }), [query, city, branch, maxFee, minPercentile]);
  const colleges = trpc.catalog.list.useQuery(input);
  return <Shell active="/colleges"><FinderHeader /><section className="container pb-20"><div className="grid gap-6 lg:grid-cols-[260px_1fr]"><aside className="h-fit rounded-[1.5rem] border border-[#e0e3f0] bg-white p-5 shadow-[0_10px_26px_rgba(44,81,61,0.04)] lg:sticky lg:top-5"><div className="flex items-center justify-between"><p className="font-display text-lg font-bold text-[#1f2a5a]">Refine search</p><SlidersHorizontal className="size-4 text-[#635bdb]" /></div><div className="mt-6 grid gap-5"><label className="grid gap-2"><span className="text-xs font-bold uppercase tracking-[0.12em] text-[#9299b2]">Search</span><div className="relative"><Search className="absolute left-3 top-1/2 size-4 -translate-y-1/2 text-[#9bb0a8]" /><input value={query} onChange={(e) => setQuery(e.target.value)} placeholder="College or city" className="input pl-9" /></div></label><SelectField label="City" value={city} onChange={setCity} options={["all", ...(filters.data?.cities ?? [])]} /><SelectField label="Branch" value={branch} onChange={setBranch} options={["all", ...(filters.data?.branches ?? [])]} /><label className="grid gap-2"><div className="flex justify-between"><span className="text-xs font-bold uppercase tracking-[0.12em] text-[#9299b2]">Max annual fee</span><span className="text-xs font-bold text-[#635bdb]">₹{(maxFee / 1000).toFixed(0)}k</span></div><input type="range" min="70000" max="300000" step="10000" value={maxFee} onChange={(e) => setMaxFee(Number(e.target.value))} className="accent-[#635bdb]" /></label><label className="grid gap-2"><div className="flex justify-between"><span className="text-xs font-bold uppercase tracking-[0.12em] text-[#9299b2]">Minimum percentile</span><span className="text-xs font-bold text-[#635bdb]">{minPercentile || "Any"}</span></div><input type="range" min="0" max="100" step="0.5" value={minPercentile} onChange={(e) => setMinPercentile(Number(e.target.value))} className="accent-[#635bdb]" /></label><button onClick={() => { setQuery(""); setCity("all"); setBranch("all"); setMaxFee(300000); setMinPercentile(0); }} className="button-soft">Reset filters</button></div></aside><div><div className="mb-5 flex flex-wrap items-center justify-between gap-3"><p className="text-sm font-semibold text-[#70877f]">{colleges.data?.length ?? 0} colleges match your view</p>{shortlist.length > 0 && <Link href={`/compare?colleges=${shortlist.join(",")}`} className="button-secondary py-2.5">Compare shortlist ({shortlist.length}) <ArrowRight className="size-4" /></Link>}</div>{colleges.isLoading ? <LoadingGrid /> : colleges.data?.length ? <div className="grid gap-4">{colleges.data.map((college) => <CollegeCard key={college.id} college={college} saved={shortlist.includes(college.slug)} onToggle={() => setShortlist((items) => items.includes(college.slug) ? items.filter((item) => item !== college.slug) : items.length < 3 ? [...items, college.slug] : items)} />)}</div> : <EmptyState />}</div></div></section></Shell>;
}

function SelectField({ label, value, onChange, options }: { label: string; value: string; onChange: (value: string) => void; options: string[] }) { return <label className="grid gap-2"><span className="text-xs font-bold uppercase tracking-[0.12em] text-[#9299b2]">{label}</span><div className="relative"><select value={value} onChange={(e) => onChange(e.target.value)} className="input appearance-none pr-8"><option value="all">All {label.toLowerCase()}s</option>{options.filter((option) => option !== "all").map((option) => <option key={option} value={option}>{option}</option>)}</select><ChevronDown className="pointer-events-none absolute right-3 top-1/2 size-4 -translate-y-1/2 text-[#9bb0a8]" /></div></label>; }

function CollegeCard({ college, saved, onToggle }: { college: College; saved: boolean; onToggle: () => void }) { const best = [...college.branches].sort((a, b) => b.gopensPercentile - a.gopensPercentile)[0]; return <article className="group grid gap-5 rounded-[1.5rem] border border-[#e0e3f0] bg-white p-5 transition duration-200 hover:-translate-y-0.5 hover:border-[#c4d9b5] hover:shadow-[0_16px_34px_rgba(44,81,61,0.08)] sm:grid-cols-[1fr_auto] sm:p-6"><div><div className="flex flex-wrap items-center gap-2"><span className="rounded-full bg-[#eef0ff] px-2.5 py-1 text-[10px] font-bold uppercase tracking-[0.12em] text-[#6963b5]">{college.type}</span>{college.autonomous && <span className="rounded-full bg-[#f4f0ff] px-2.5 py-1 text-[10px] font-bold uppercase tracking-[0.12em] text-[#635bdb]">Autonomous</span>}</div><div className="mt-4 flex items-start gap-3"><span className="grid size-11 shrink-0 place-items-center rounded-2xl bg-[#1f2a5a] font-display text-lg font-bold text-[#d8d9ff]">{college.shortName.slice(0, 2)}</span><div><Link href={`/college/${college.slug}`} className="font-display text-xl font-bold tracking-[-0.035em] text-[#1f2a5a] hover:text-[#635bdb]">{college.name}</Link><p className="mt-1 flex items-center gap-1 text-sm text-[#7b9189]"><MapPin className="size-3.5" />{college.city}, {college.state}</p></div></div><div className="mt-5 flex flex-wrap gap-2">{college.highlights.map((item) => <span key={item} className="rounded-lg bg-[#f5f6ff] px-2.5 py-1.5 text-xs font-semibold text-[#688079]">{item}</span>)}</div><div className="mt-5 flex flex-wrap items-center gap-4 border-t border-[#edf0f6] pt-4 text-sm"><span><span className="text-xs text-[#9299b2]">Best cutoff</span><strong className="ml-2 text-[#1f2a5a]">{best.gopensPercentile.toFixed(2)}%ile</strong></span><span><span className="text-xs text-[#9299b2]">Annual fee</span><strong className="ml-2 text-[#1f2a5a]">₹{(college.annualFees / 1000).toFixed(0)}k</strong></span><span><span className="text-xs text-[#9299b2]">Placement</span><strong className="ml-2 text-[#1f2a5a]">{college.placement.placementRate}%</strong></span></div></div><div className="flex flex-row items-end justify-between gap-3 sm:flex-col sm:items-end"><button onClick={onToggle} className={cx("icon-button", saved && "icon-button-saved")} aria-label={saved ? "Remove from shortlist" : "Add to shortlist"}>{saved ? <Heart className="size-4 fill-current" /> : <Bookmark className="size-4" />}</button><Link href={`/college/${college.slug}`} className="button-primary whitespace-nowrap">View profile <ArrowRight className="size-4" /></Link></div></article>; }

function LoadingGrid() { return <div className="grid gap-4">{[1, 2, 3].map((item) => <div key={item} className="h-56 animate-pulse rounded-[1.5rem] bg-[#e8f0e4]" />)}</div>; }
function EmptyState() { return <div className="rounded-[1.5rem] border border-dashed border-[#cfd3ea] bg-[#f5f6ff] p-12 text-center"><Search className="mx-auto size-8 text-[#c0d0bc]" /><h3 className="mt-4 font-display text-xl font-bold text-[#1f2a5a]">No colleges match this view</h3><p className="mx-auto mt-2 max-w-sm text-sm leading-6 text-[#70877f]">Try widening the fee range or lowering the percentile filter to see more options.</p></div>; }
function useShortlist(): [string[], (next: string[] | ((items: string[]) => string[])) => void] { const [items, setItems] = useState<string[]>(() => { try { return JSON.parse(localStorage.getItem("educompass-shortlist") ?? "[]"); } catch { return []; } }); useEffect(() => { localStorage.setItem("educompass-shortlist", JSON.stringify(items)); }, [items]); return [items, setItems]; }

export function CollegeDetail() { const { slug = "" } = useParams<{ slug: string }>(); const college = trpc.catalog.get.useQuery({ slug }); const [shortlist, setShortlist] = useShortlist(); if (college.isLoading) return <Shell><div className="container py-24"><LoadingGrid /></div></Shell>; if (!college.data) return <Shell><div className="container py-24"><EmptyState /></div></Shell>; const data = college.data; return <Shell active="/colleges"><div className="container pb-20 pt-10"><Link href="/colleges" className="inline-flex items-center gap-2 text-sm font-bold text-[#718880] hover:text-[#635bdb]"><ArrowRight className="size-4 rotate-180" /> Back to finder</Link><div className="mt-8 grid gap-8 lg:grid-cols-[1fr_330px]"><div><div className="flex flex-wrap gap-2"><span className="rounded-full bg-[#eef0ff] px-3 py-1.5 text-[10px] font-bold uppercase tracking-[0.12em] text-[#6963b5]">{data.type}</span><span className="rounded-full bg-[#f4f0ff] px-3 py-1.5 text-[10px] font-bold uppercase tracking-[0.12em] text-[#635bdb]">{data.city}</span></div><h1 className="mt-4 max-w-3xl font-display text-4xl font-bold leading-[1.02] tracking-[-0.06em] text-[#1f2a5a] sm:text-6xl">{data.name}</h1><p className="mt-5 max-w-2xl text-base leading-8 text-[#727b9c]">{data.description}</p><div className="mt-7 flex flex-wrap gap-3"><button onClick={() => setShortlist((items) => items.includes(data.slug) ? items.filter((item) => item !== data.slug) : items.length < 3 ? [...items, data.slug] : items)} className={data && shortlist.includes(data.slug) ? "button-secondary" : "button-primary"}>{shortlist.includes(data.slug) ? <Check className="size-4" /> : <Bookmark className="size-4" />} {shortlist.includes(data.slug) ? "In shortlist" : "Add to shortlist"}</button><a href={data.website} target="_blank" rel="noreferrer" className="button-ghost">Official website <ExternalLink className="size-4" /></a><a href={data.mapUrl} target="_blank" rel="noreferrer" className="button-ghost"><MapPin className="size-4" /> View map</a></div></div><div className="rounded-[1.5rem] bg-[#1f2a5a] p-6 text-[#f7f7ff]"><p className="eyebrow text-[#c1c8e5]">At a glance</p><div className="mt-6 grid grid-cols-2 gap-4"><Snapshot label="Established" value={String(data.established)} /><Snapshot label="Annual fee" value={data.isOfficial2026 ? "See site" : `₹${(data.annualFees / 1000).toFixed(0)}k`} /><Snapshot label="Intake" value={data.isOfficial2026 ? "See site" : `${data.intake}`} /><Snapshot label="Placement" value={data.isOfficial2026 ? "See site" : `${data.placement.placementRate}%`} /></div><div className="mt-6 rounded-2xl bg-[#303b70] p-4"><p className="text-xs font-bold uppercase tracking-[0.1em] text-[#c1c8e5]">Top recruiters</p><p className="mt-2 text-sm leading-6 text-[#e3e5f4]">{data.placement.recruiters.join(" · ")}</p></div></div></div><div className="mt-12 grid gap-5 lg:grid-cols-[1.2fr_0.8fr]"><section className="rounded-[1.5rem] border border-[#e0e3f0] bg-white p-6 sm:p-7"><div className="flex flex-col justify-between gap-3 sm:flex-row sm:items-end"><div><Eyebrow>Branch-wise cutoffs</Eyebrow><h2 className="mt-2 font-display text-2xl font-bold tracking-[-0.045em] text-[#1f2a5a]">{data.isOfficial2026 ? "CAP Round I, II, III & IV · 2026–27" : "CAP Round I, 2025–26"}</h2></div><span className="rounded-full bg-[#f4f0ff] px-3 py-1.5 text-[10px] font-bold uppercase tracking-[0.12em] text-[#635bdb]">GOPENS · MHT-CET</span></div>{data.isOfficial2026 ? <OfficialCutoffTable cutoffs={data.branches} /> : <CutoffTable cutoffs={data.branches} compact={false} />}<p className="mt-4 text-xs leading-5 text-[#9299b2]">{data.isOfficial2026 ? "Official Maharashtra State CET Cell 2026–27 MH cutoffs. Every row preserves CAP round, stage, category, closing merit rank, and percentile from the source publication. If a branch has no row for a round, the official PDF did not publish a cutoff for that branch in that round." : "Official Maharashtra State CET Cell cutoffs. Merit percentile is shown in brackets in the source publication; the table here shows the GOPENS state-level percentile for fast comparison."}</p>{data.isOfficial2026 ? <div className="mt-4 flex flex-wrap gap-2">{([1, 2, 3, 4] as const).map((round) => <a key={round} href={data.officialRoundSources?.[round]} target="_blank" rel="noreferrer" className="rounded-full bg-[#f4f0ff] px-3 py-1.5 text-[10px] font-bold uppercase tracking-[0.1em] text-[#635bdb]">CAP {round} PDF <ExternalLink className="ml-1 inline size-3" /></a>)}</div> : <a href={data.officialCutoffSource} target="_blank" rel="noreferrer" className="mt-3 inline-flex items-center gap-2 text-xs font-bold text-[#635bdb]">View official cutoff publication <ExternalLink className="size-3.5" /></a>}</section><section className="grid gap-5"><div className="rounded-[1.5rem] border border-[#e0e3f0] bg-[#eef0ff] p-6"><Eyebrow>Placement signal</Eyebrow><div className="mt-3 flex items-end justify-between"><span className="font-display text-4xl font-bold tracking-[-0.06em] text-[#1f2a5a]">₹{data.placement.average}L</span><span className="text-xs font-bold text-[#6c66b2]">average package</span></div><div className="mt-5 h-2 rounded-full bg-[#dfe1f3]"><div className="h-2 rounded-full bg-[#635bdb]" style={{ width: `${Math.min(data.placement.placementRate, 100)}%` }} /></div><div className="mt-2 flex justify-between text-xs font-semibold text-[#727b9c]"><span>{data.placement.placementRate}% placed</span><span>₹{data.placement.highest}L highest</span></div></div><div className="rounded-[1.5rem] border border-[#e0e3f0] bg-white p-6"><Eyebrow>Why students shortlist it</Eyebrow><div className="mt-4 grid gap-3">{data.highlights.map((highlight) => <div key={highlight} className="flex items-start gap-2.5 text-sm font-semibold text-[#46665c]"><span className="mt-0.5 grid size-5 place-items-center rounded-full bg-[#e5e4ff] text-[#625daf]"><Check className="size-3" /></span>{highlight}</div>)}</div></div></section></div></div></Shell>; }
function Snapshot({ label, value }: { label: string; value: string }) { return <div><p className="text-[10px] font-bold uppercase tracking-[0.11em] text-[#c1c8e5]">{label}</p><p className="mt-1 font-display text-xl font-bold tracking-[-0.04em] text-[#f7f7ff]">{value}</p></div>; }

function OfficialCutoffTable({ cutoffs }: { cutoffs: Cutoff[] }) {
  const rows = cutoffs.flatMap((cutoff) => (cutoff.officialRounds ?? []).map((record) => ({ cutoff, record })));
  return <div className="mt-6 grid gap-4">{rows.map(({ cutoff, record }, index) => <div key={`${cutoff.code}-${record.round}-${record.stage}-${index}`} className="rounded-2xl border border-[#e5e4f4] bg-[#fbfbff] p-4"><div className="flex flex-col justify-between gap-2 sm:flex-row sm:items-center"><div><p className="font-semibold text-[#1f2a5a]">{cutoff.branch}</p><p className="mt-1 text-[10px] font-bold uppercase tracking-[0.12em] text-[#9299b2]">CAP Round {record.round} · Stage {record.stage} · {cutoff.code}</p></div><a href={record.source} target="_blank" rel="noreferrer" className="text-xs font-bold text-[#635bdb]">Official PDF <ExternalLink className="ml-1 inline size-3" /></a></div><div className="mt-4 grid gap-2 sm:grid-cols-2 lg:grid-cols-3">{Object.entries(record.categories).map(([category, value]) => <div key={category} className="rounded-xl border border-[#e7e7f3] bg-white px-3 py-2"><div className="flex items-center justify-between gap-2"><span className="text-[10px] font-bold uppercase tracking-[0.1em] text-[#635bdb]">{category}</span><span className="text-[10px] font-semibold text-[#9299b2]">Merit rank</span></div><div className="mt-1 flex items-end justify-between"><strong className="text-sm text-[#3c4776]">{value.percentile.toFixed(4)}%ile</strong><span className="text-xs font-semibold text-[#727b9c]">{value.rank.toLocaleString("en-IN")}</span></div></div>)}</div></div>)}</div>; }

function CutoffTable({ cutoffs, compact }: { cutoffs: Cutoff[]; compact: boolean }) { return <div className="mt-6 overflow-x-auto"><table className="w-full min-w-[550px] text-left"><thead><tr className="border-b border-[#e6eee3] text-[10px] font-bold uppercase tracking-[0.12em] text-[#90a49c]"><th className="pb-3 pr-4">Branch</th><th className="pb-3 pr-4">GOPENS percentile</th><th className="pb-3 pr-4">Last merit rank</th><th className="pb-3">Round</th></tr></thead><tbody>{cutoffs.map((cutoff) => <tr key={cutoff.code} className="border-b border-[#eef3eb] last:border-0"><td className={cx("py-4 pr-4 font-semibold text-[#3c4776]", compact && "py-3 text-sm")}>{cutoff.branch}</td><td className="py-4 pr-4"><span className="rounded-lg bg-[#e5e4ff] px-2.5 py-1.5 text-sm font-bold text-[#5d58a7]">{cutoff.gopensPercentile.toFixed(2)}%</span></td><td className="py-4 pr-4 text-sm font-semibold text-[#71877f]">{cutoff.lastRank.toLocaleString("en-IN")}</td><td className="py-4 text-xs font-semibold text-[#9299b2]">{cutoff.round}</td></tr>)}</tbody></table></div>; }

export function ComparePage() { const [, setLocation] = useLocation(); const [shortlist, setShortlist] = useShortlist(); const params = new URLSearchParams(typeof window !== "undefined" ? window.location.search : ""); const slugs = useMemo(() => (params.get("colleges") ?? shortlist.join(",")).split(",").filter(Boolean).slice(0, 3), [shortlist]); const comparison = trpc.catalog.compare.useQuery({ slugs }); return <Shell active="/compare"><div className="container pb-20 pt-12 sm:pt-16"><Eyebrow>Comparison studio</Eyebrow><div className="flex flex-col justify-between gap-5 md:flex-row md:items-end"><div><h1 className="mt-2 font-display text-4xl font-bold tracking-[-0.06em] text-[#1f2a5a] sm:text-5xl">See your shortlist side by side.</h1><p className="mt-4 max-w-2xl text-[15px] leading-7 text-[#727b9c]">Three colleges is usually enough to spot the trade-offs. Compare cutoffs, cost, outcomes, and fit without losing the source trail.</p></div>{slugs.length > 0 && <button onClick={() => { setShortlist([]); setLocation("/compare"); }} className="button-ghost text-red-600">Clear shortlist <X className="size-4" /></button>}</div>{!slugs.length ? <div className="mt-12 rounded-[1.75rem] border border-dashed border-[#cfd3ea] bg-[#f5f6ff] p-12 text-center"><ScaleIcon /><h2 className="mt-4 font-display text-2xl font-bold text-[#1f2a5a]">Your comparison is waiting</h2><p className="mx-auto mt-2 max-w-md text-sm leading-6 text-[#70877f]">Add up to three colleges from the finder, then come back here to compare them.</p><Link href="/colleges" className="button-primary mt-7">Explore colleges <ArrowRight className="size-4" /></Link></div> : comparison.isLoading ? <div className="mt-10"><LoadingGrid /></div> : <div className="mt-10 overflow-x-auto rounded-[1.5rem] border border-[#e0e3f0] bg-white"><table className="w-full min-w-[800px] text-left"><thead><tr><th className="w-[180px] border-b border-[#edf0f6] p-5 text-xs font-bold uppercase tracking-[0.12em] text-[#90a49c]">Decision lens</th>{comparison.data?.map((college) => <th key={college.id} className="border-b border-l border-[#edf0f6] p-5 align-top"><span className="grid size-10 place-items-center rounded-xl bg-[#1f2a5a] font-display font-bold text-[#d8d9ff]">{college.shortName.slice(0, 2)}</span><Link href={`/college/${college.slug}`} className="mt-3 block font-display text-xl font-bold leading-tight tracking-[-0.04em] text-[#1f2a5a] hover:text-[#635bdb]">{college.shortName}</Link><p className="mt-1 text-xs font-semibold text-[#9299b2]">{college.city}</p></th>)}</tr></thead><tbody><CompareRow label="Best branch cutoff">{comparison.data?.map((college) => <span key={college.id} className="font-bold text-[#5f7b31]">{Math.max(...college.branches.map((b) => b.gopensPercentile)).toFixed(2)}%ile</span>)}</CompareRow><CompareRow label="Annual fee">{comparison.data?.map((college) => <span key={college.id} className="font-bold text-[#3c4776]">₹{college.annualFees.toLocaleString("en-IN")}</span>)}</CompareRow><CompareRow label="Placement rate">{comparison.data?.map((college) => <span key={college.id} className="font-bold text-[#3c4776]">{college.placement.placementRate}%</span>)}</CompareRow><CompareRow label="Average package">{comparison.data?.map((college) => <span key={college.id} className="font-bold text-[#3c4776]">₹{college.placement.average}L</span>)}</CompareRow><CompareRow label="Branches">{comparison.data?.map((college) => <span key={college.id} className="text-sm font-semibold text-[#668078]">{college.branches.length} tracked</span>)}</CompareRow><tr><td className="border-t border-[#edf0f6] p-5 text-xs font-bold uppercase tracking-[0.1em] text-[#90a49c]">Cutoffs</td>{comparison.data?.map((college) => <td key={college.id} className="border-l border-t border-[#edf0f6] p-5 align-top"><CutoffTable cutoffs={college.branches.slice(0, 4)} compact /></td>)}</tr></tbody></table></div>}</div></Shell>; }
function CompareRow({ label, children }: { label: string; children: ReactNode[] | undefined }) { return <tr><td className="border-t border-[#edf0f6] p-5 text-xs font-bold uppercase tracking-[0.1em] text-[#90a49c]">{label}</td>{children?.map((child, index) => <td key={index} className="border-l border-t border-[#edf0f6] p-5">{child}</td>)}</tr>; }

export function Guidance() { const [percentile, setPercentile] = useState(98.5); const [branch, setBranch] = useState("all"); const filters = trpc.catalog.filters.useQuery(); const recommendations = trpc.catalog.recommendations.useQuery({ percentile, branch }); return <Shell active="/guidance"><div className="container pb-20 pt-12 sm:pt-16"><div className="grid gap-10 lg:grid-cols-[0.9fr_1.1fr] lg:items-start"><div><Eyebrow>Admission guidance</Eyebrow><h1 className="mt-2 font-display text-4xl font-bold leading-[1.02] tracking-[-0.06em] text-[#1f2a5a] sm:text-5xl">Turn your percentile into a plan.</h1><p className="mt-5 max-w-xl text-[15px] leading-7 text-[#727b9c]">Use the signal tool for a first-pass shortlist. It is a guide, not a guarantee — category, home university, round, and seat type can change the actual outcome.</p><div className="mt-8 rounded-[1.5rem] border border-[#e0e3f0] bg-white p-6"><div className="flex items-end justify-between"><div><p className="eyebrow">Your percentile</p><p className="mt-2 font-display text-4xl font-bold tracking-[-0.05em] text-[#1f2a5a]">{percentile.toFixed(2)}</p></div><Gauge className="size-7 text-[#635bdb]" /></div><input type="range" min="70" max="100" step="0.01" value={percentile} onChange={(e) => setPercentile(Number(e.target.value))} className="mt-6 w-full accent-[#635bdb]" /><div className="mt-5"><SelectField label="Preferred branch" value={branch} onChange={setBranch} options={["all", ...(filters.data?.branches ?? [])]} /></div></div></div><div><div className="mb-5 flex items-center justify-between"><div><Eyebrow>Closest signals</Eyebrow><h2 className="mt-2 font-display text-2xl font-bold tracking-[-0.04em] text-[#1f2a5a]">A first-pass shortlist</h2></div><span className="rounded-full bg-[#eef0ff] px-3 py-1.5 text-[10px] font-bold uppercase tracking-[0.12em] text-[#6963b5]">Not a guarantee</span></div><div className="grid gap-3">{recommendations.data?.slice(0, 5).map((item: any) => <div key={`${item.college.id}-${item.branch.code}`} className="rounded-[1.3rem] border border-[#e0e3f0] bg-white p-5"><div className="flex items-start justify-between gap-4"><div><Link href={`/college/${item.college.slug}`} className="font-display text-lg font-bold text-[#1f2a5a] hover:text-[#635bdb]">{item.college.shortName} <span className="font-sans text-xs font-semibold text-[#9299b2]">· {item.college.city}</span></Link><p className="mt-1 text-sm font-semibold text-[#6b8179]">{item.branch.branch}</p></div><span className={cx("rounded-full px-2.5 py-1.5 text-[10px] font-bold", item.verdict === "Strong chance" ? "bg-[#e5e4ff] text-[#5d58a7]" : "bg-[#f4f0ff] text-[#635bdb]")}>{item.verdict}</span></div><div className="mt-4 flex items-center justify-between text-xs"><span className="text-[#9299b2]">Official GOPENS cutoff</span><strong className="text-[#3c4776]">{item.branch.gopensPercentile.toFixed(2)}%ile <span className="ml-2 font-normal text-[#9299b2]">({item.gap > 0 ? "+" : ""}{item.gap.toFixed(2)} gap)</span></strong></div><div className="mt-2 h-1.5 rounded-full bg-[#edf2ea]"><div className="h-1.5 rounded-full bg-[#635bdb]" style={{ width: `${Math.min(100, Math.max(4, item.branch.gopensPercentile))}%` }} /></div></div>)}</div></div></div><div className="mt-14 grid gap-4 md:grid-cols-3"><GuideCard icon={<BookOpen />} title="Read the fine print" body="Cutoffs vary by category, seat type, home university, CAP round, and year." /><GuideCard icon={<Target />} title="Keep three buckets" body="Build ambitious, realistic, and safe options instead of one single list." /><GuideCard icon={<CircleHelp />} title="Verify before you apply" body="Use the official CET Cell notice and college website for current-year decisions." /></div></div></Shell>; }
function GuideCard({ icon, title, body }: { icon: ReactNode; title: string; body: string }) { return <div className="rounded-[1.4rem] border border-[#e0e3f0] bg-[#f5f6ff] p-6"><span className="grid size-10 place-items-center rounded-xl bg-white text-[#635bdb] shadow-sm">{icon}</span><h3 className="mt-6 font-display text-lg font-bold text-[#1f2a5a]">{title}</h3><p className="mt-2 text-sm leading-6 text-[#727b9c]">{body}</p></div>; }

export function StudentWorkspace() { const { user, isAuthenticated, loading, logout } = useAuthSafe(); const workspace = trpc.student.workspace.useQuery(undefined, { enabled: isAuthenticated }); const [shortlist] = useShortlist(); const comparison = trpc.catalog.compare.useQuery({ slugs: shortlist }, { enabled: shortlist.length > 0 }); return <Shell active="/student"><div className="container pb-20 pt-12 sm:pt-16">{loading ? <LoadingGrid /> : !isAuthenticated ? <div className="mx-auto max-w-2xl rounded-[2rem] border border-[#e0e3f0] bg-white p-8 text-center shadow-[0_16px_40px_rgba(44,81,61,0.06)] sm:p-12"><span className="mx-auto grid size-14 place-items-center rounded-2xl bg-[#1f2a5a] text-[#d8d9ff]"><LockKeyhole className="size-6" /></span><Eyebrow>Student workspace</Eyebrow><h1 className="mt-2 font-display text-4xl font-bold tracking-[-0.06em] text-[#1f2a5a]">Keep your college search in one place.</h1><p className="mx-auto mt-4 max-w-md text-[15px] leading-7 text-[#727b9c]">Sign in to return to your saved shortlist and keep your next steps close at hand.</p><button onClick={startLogin} className="button-primary mt-7">Continue with student login <ArrowRight className="size-4" /></button></div> : <><div className="flex flex-col justify-between gap-5 md:flex-row md:items-end"><div><Eyebrow>Your workspace</Eyebrow><h1 className="mt-2 font-display text-4xl font-bold tracking-[-0.06em] text-[#1f2a5a] sm:text-5xl">Welcome back, {user?.name?.split(" ")[0] ?? "student"}.</h1><p className="mt-4 text-[15px] leading-7 text-[#727b9c]">Your shortlist is ready when you are.</p></div><button onClick={() => void logout()} className="button-ghost text-red-600"><LogOut className="size-4" /> Log out</button></div><div className="mt-10 grid gap-4 md:grid-cols-3"><WorkspaceMetric value={String(shortlist.length).padStart(2, "0")} label="shortlisted colleges" icon={<Bookmark />} /><WorkspaceMetric value={String(comparison.data?.length ?? 0).padStart(2, "0")} label="ready to compare" icon={<BarChart3 />} /><WorkspaceMetric value="2025–26" label="cutoff context" icon={<ShieldCheck />} /></div><div className="mt-10 grid gap-5 lg:grid-cols-[1fr_0.75fr]"><div className="rounded-[1.5rem] border border-[#e0e3f0] bg-white p-6 sm:p-7"><div className="flex items-center justify-between"><div><Eyebrow>Next steps</Eyebrow><h2 className="mt-2 font-display text-2xl font-bold text-[#1f2a5a]">Your decision checklist</h2></div><span className="grid size-10 place-items-center rounded-xl bg-[#f4f0ff] text-[#635bdb]"><Check className="size-5" /></span></div><div className="mt-6 grid gap-3">{workspace.data?.nextSteps.map((step, index) => <div key={step} className="flex items-start gap-3 rounded-xl bg-[#f5f6ff] p-4"><span className="grid size-6 shrink-0 place-items-center rounded-full bg-[#e5e4ff] text-xs font-bold text-[#68862f]">{index + 1}</span><span className="text-sm font-semibold text-[#46665c]">{step}</span></div>)}</div></div><div className="rounded-[1.5rem] bg-[#1f2a5a] p-6 text-[#f7f7ff] sm:p-7"><p className="eyebrow text-[#c1c8e5]">Shortlist health</p><h2 className="mt-2 font-display text-2xl font-bold">A small list is a strong list.</h2><p className="mt-3 text-sm leading-6 text-[#cbd1ed]">Keep your shortlist to three colleges for a clean comparison. You can always add more from the finder later.</p><Link href={shortlist.length ? `/compare?colleges=${shortlist.join(",")}` : "/colleges"} className="mt-7 inline-flex items-center gap-2 text-sm font-bold text-[#d8d9ff]">{shortlist.length ? "Open comparison" : "Find colleges"} <ArrowRight className="size-4" /></Link></div></div></>}</div></Shell>; }
function WorkspaceMetric({ value, label, icon }: { value: string; label: string; icon: ReactNode }) { return <div className="rounded-[1.3rem] border border-[#e0e3f0] bg-white p-5"><span className="text-[#635bdb]">{icon}</span><p className="mt-3 font-display text-3xl font-bold tracking-[-0.05em] text-[#1f2a5a]">{value}</p><p className="mt-1 text-xs font-bold uppercase tracking-[0.12em] text-[#9299b2]">{label}</p></div>; }

export function AdminPage() { const { isAuthenticated } = useAuthSafe(); const admin = trpc.admin.overview.useQuery(undefined, { enabled: isAuthenticated }); return <Shell active="/admin"><div className="container pb-20 pt-12 sm:pt-16"><div className="mx-auto max-w-4xl"><Eyebrow>Admin console</Eyebrow><h1 className="mt-2 font-display text-4xl font-bold tracking-[-0.06em] text-[#1f2a5a] sm:text-5xl">Verified source registry.</h1><p className="mt-4 max-w-2xl text-[15px] leading-7 text-[#727b9c]">Protected data-review surface for maintaining college records, branch cutoffs, and official source links.</p>{!isAuthenticated ? <div className="mt-10 rounded-[1.5rem] border border-[#e0e3f0] bg-white p-8"><div className="flex items-start gap-4"><span className="grid size-11 place-items-center rounded-xl bg-[#f4f0ff] text-[#635bdb]"><LockKeyhole className="size-5" /></span><div><h2 className="font-display text-xl font-bold text-[#1f2a5a]">Admin authentication required</h2><p className="mt-2 text-sm leading-6 text-[#727b9c]">Sign in with the protected account to access source review and record management.</p><button onClick={startLogin} className="button-primary mt-5">Open secure login <ArrowRight className="size-4" /></button></div></div></div> : admin.isLoading ? <div className="mt-10"><LoadingGrid /></div> : admin.error ? <div className="mt-10 rounded-[1.5rem] border border-[#ddd7f0] bg-[#f7f5ff] p-8"><h2 className="font-display text-xl font-bold text-[#514c98]">Access is restricted</h2><p className="mt-2 text-sm leading-6 text-[#7772ab]">This account is authenticated but does not have admin role access. The public finder remains available.</p></div> : <div className="mt-10"><div className="grid gap-4 sm:grid-cols-3"><Metric value={admin.data?.records ?? 0} label="college records" /><Metric value="1" label="cutoff source" /><Metric value="GOPENS" label="default category" /></div><div className="mt-6 overflow-hidden rounded-[1.5rem] border border-[#e0e3f0] bg-white"><div className="border-b border-[#edf0f6] p-5"><h2 className="font-display text-xl font-bold text-[#1f2a5a]">Managed colleges</h2></div><div className="divide-y divide-[#eef3eb]">{admin.data?.colleges.map((college) => <div key={college.id} className="flex flex-col justify-between gap-3 p-5 sm:flex-row sm:items-center"><div><p className="font-semibold text-[#3c4776]">{college.name}</p><p className="mt-1 text-xs text-[#9299b2]">{college.city} · {college.branches.length} branches tracked</p></div><a href={college.officialCutoffSource} target="_blank" rel="noreferrer" className="inline-flex items-center gap-2 text-xs font-bold text-[#635bdb]">Source <ExternalLink className="size-3.5" /></a></div>)}</div></div></div>}</div></div></Shell>; }

export function About() { return <Shell active="/about"><div className="container pb-20 pt-12 sm:pt-16"><div className="grid gap-10 lg:grid-cols-[0.8fr_1.2fr] lg:items-start"><div><Eyebrow>About EduCompass</Eyebrow><h1 className="mt-2 font-display text-4xl font-bold leading-[1.02] tracking-[-0.06em] text-[#1f2a5a] sm:text-5xl">Less tab-hopping. More clarity.</h1></div><div className="rounded-[1.75rem] bg-[#1f2a5a] p-7 text-[#f7f7ff] sm:p-10"><p className="font-display text-2xl font-bold leading-tight tracking-[-0.04em] sm:text-3xl">EduCompass is a centralized engineering college discovery and guidance system.</p><p className="mt-6 max-w-2xl text-[15px] leading-7 text-[#d0d5f0]">It brings together college profiles, branch-wise MHT-CET cutoffs, fees, intake, placement signals, and source links so students and parents can evaluate options more efficiently.</p><div className="mt-8 grid gap-3 sm:grid-cols-3"><AboutStat icon={<Search />} label="Discover" /><AboutStat icon={<BarChart3 />} label="Compare" /><AboutStat icon={<Target />} label="Decide" /></div></div></div><div className="mt-14 grid gap-4 md:grid-cols-2"><div className="rounded-[1.5rem] border border-[#e0e3f0] bg-white p-7"><Eyebrow>Data context</Eyebrow><h2 className="mt-3 font-display text-2xl font-bold text-[#1f2a5a]">Transparent by default.</h2><p className="mt-3 text-sm leading-7 text-[#727b9c]">The cutoff cards in this demo use the official Maharashtra State CET Cell CAP Round I 2025–26 publication, with GOPENS state-level percentiles surfaced for quick comparison. Always check the latest official notification for the year and category that applies to you.</p><a href="https://cetcell.mahacet.org/cutoff-explorer/" target="_blank" rel="noreferrer" className="mt-5 inline-flex items-center gap-2 text-sm font-bold text-[#635bdb]">Open CET Cell cutoff explorer <ExternalLink className="size-4" /></a></div><div className="rounded-[1.5rem] border border-[#e0e3f0] bg-[#eef0ff] p-7"><Eyebrow>Future-ready</Eyebrow><h2 className="mt-3 font-display text-2xl font-bold text-[#1f2a5a]">A foundation for better guidance.</h2><p className="mt-3 text-sm leading-7 text-[#727b9c]">The platform can grow into predictive admission analytics, option-form planning, mobile access, deadline alerts, and direct CAP data feeds.</p><Link href="/guidance" className="mt-5 inline-flex items-center gap-2 text-sm font-bold text-[#635bdb]">Try the guidance tool <ArrowRight className="size-4" /></Link></div></div></div></Shell>; }
function AboutStat({ icon, label }: { icon: ReactNode; label: string }) { return <div className="flex items-center gap-2 rounded-xl bg-[#303b70] px-3 py-3 text-sm font-semibold text-[#dfe2f5]"><span className="text-[#d8d9ff]">{icon}</span>{label}</div>; }

export { Home, Finder, Shell };
